//! Kubernetes-independent Agones domain model.
//!
//! The core intentionally contains no `k8s-*` dependency. Rusternetes adapters
//! can map their API/runtime types into this model without making Kubernetes
//! compatibility the architectural center of the Rust reimplementation.

// The resource derive uses this stable path in both this library and its
// same-package integration targets; downstream Cargo aliases are resolved.
extern crate self as agones_core;

/// Static Kubernetes API identity for a stored Agones resource.
///
/// Implementations are generated by `#[derive(agones_macros::AgonesApiResource)]`
/// so adapters and controllers can be generic over resource identity without
/// importing a Kubernetes runtime into this crate.
pub trait AgonesApiResource {
    const GROUP: &'static str;
    const VERSION: &'static str;
    const API_VERSION: &'static str;
    const KIND: &'static str;
    const PLURAL: &'static str;
}

pub mod fleet;
pub mod allocation;
pub mod autoscaling;
pub mod gameserver;
pub mod gameserverset;
