#[cfg(test)]
mod api_resource_identity_tests {
    use super::*;

    fn identity<T: AgonesApiResource>() -> (&'static str, &'static str, &'static str, &'static str) {
        (T::GROUP, T::API_VERSION, T::KIND, T::PLURAL)
    }

    #[test]
    fn stored_resources_publish_exact_agones_api_identity() {
        assert_eq!(
            identity::<GameServer>(),
            ("agones.dev", "agones.dev/v1", "GameServer", "gameservers")
        );
        assert_eq!(
            identity::<GameServerSet>(),
            (
                "agones.dev",
                "agones.dev/v1",
                "GameServerSet",
                "gameserversets"
            )
        );
        assert_eq!(
            identity::<Fleet>(),
            ("agones.dev", "agones.dev/v1", "Fleet", "fleets")
        );
        assert_eq!(
            identity::<FleetAutoscaler>(),
            (
                "autoscaling.agones.dev",
                "autoscaling.agones.dev/v1",
                "FleetAutoscaler",
                "fleetautoscalers"
            )
        );
        assert_eq!(
            identity::<GameServerAllocationPolicy>(),
            (
                "multicluster.agones.dev",
                "multicluster.agones.dev/v1",
                "GameServerAllocationPolicy",
                "gameserverallocationpolicies"
            )
        );
    }
}
